        string id=S(person,"id"),trade=S(person,"trade"),label=trade=="emigrant"?"emigrant bound for America":trade=="lodging_keeper"?"lodging house keeper":trade=="runner"?"runner":trade=="infant"?"infant":"child";
        C.Execute("INSERT OR IGNORE INTO npc(id,name,role,district,faction,persona_json,spot_id,active) VALUES($p0,$p1,$p2,'rijnkaai',$p3,'{}',NULL,1)",id,S(person,"name"),label,person["faction"]==null?null:S(person,"faction"));C.Execute("UPDATE npc SET active=1 WHERE id=$p0",id);C.Execute("INSERT OR IGNORE INTO npc_relationship(npc_id) VALUES($p0)",id);C.Execute("INSERT INTO resident(id,household,trade,data_json,persona) VALUES($p0,$p1,$p2,$p3,'') ON CONFLICT(id) DO UPDATE SET household=excluded.household,trade=excluded.trade,data_json=excluded.data_json",id,(int)N(person,"household"),trade,person.ToJsonString());
    }
    private List<JsonObject> FreeDoors()
    {
        var people=People.ToArray();var used=people.Select(r=>(int)N(r["home"],"house")).ToHashSet();used.UnionWith(InworldHouses?.Invoke()??new HashSet<int>());var occupied=new List<(double x,double z)>();foreach(var r in people){occupied.Add((N(r["home"],"sx"),N(r["home"],"sz")));if(r["work"]?["door"]is JsonArray d)occupied.Add((V(d[0]),V(d[1])));}var town=C.World("town");if(town?["places"]is JsonObject places)foreach(var p in places)if(p.Value?["door"]is JsonArray d)occupied.Add((V(d[0]),V(d[1])));foreach(var shop in A(town?["shops"]))if(shop?["door"]is JsonArray d)occupied.Add((V(d[0]),V(d[1])));
        foreach(string key in new[]{"homes","poesje:door","press"}){var world=C.World(key);foreach(var home in A(world?["homes"])){if(home?["house"]!=null)used.Add((int)N(home,"house"));if(home?["step"]is JsonArray d)occupied.Add((V(d[0]),V(d[1])));}if(world?["sx"]!=null&&world["sz"]!=null)occupied.Add((N(world,"sx"),N(world,"sz")));if(world?["post"]?["step"]is JsonArray step)occupied.Add((V(step[0]),V(step[1])));}
        return (Doors?.Invoke()??Array.Empty<JsonObject>()).Where(d=>!used.Contains((int)N(d,"house"))&&!occupied.Any(p=>D(p.x,p.z,N(d,"sx"),N(d,"sz"))<4)).ToList();
    }
    private (JsonObject door,bool shared) PickLogement(List<JsonObject> free)
    {
        double Score(JsonObject d)=>D(N(d,"sx"),N(d,"sz"),20,46)+(V(d["out"]?[1])<-.7?0:25)+(N(d,"storeys")>=3?0:10);var door=free.Where(d=>D(N(d,"sx"),N(d,"sz"),20,46)<90).OrderBy(Score).FirstOrDefault();if(door!=null)return(door,false);var kept=InworldHouses?.Invoke()??new HashSet<int>();return((Doors?.Invoke()??Array.Empty<JsonObject>()).Where(d=>!kept.Contains((int)N(d,"house"))).OrderBy(Score).FirstOrDefault()??throw new InvalidOperationException("No native house doors available for the Logement"),true);
    }
    public bool Ensure(uint seed)
    {
        if(!People.Any())return false;if(State is {} had&&N(had,"v")==1){if(Doors!=null)Rehouse(had);Tick(true);return false;}
        var free=FreeDoors();var (door,shared)=PickLogement(free);var runnerDoor=free.Where(d=>N(d,"house")!=N(door,"house")).OrderBy(d=>D(N(d,"sx"),N(d,"sz"),-40,62)).FirstOrDefault()??door;var rng=Random(seed^0x1873e);int household=People.Where(r=>N(r,"household")<9000).Select(r=>(int)N(r,"household")).DefaultIfEmpty().Max()+1;
        var keeper=A(Facts["keeperPrototypes"])[0]!.DeepClone().AsObject();keeper["first"]=new[]{"Wilhelmina","Gertrud","Dorothea","Henriette"}[(int)(rng()*4)];keeper["name"]=S(keeper,"first")+" Kruger";keeper["age"]=46+(int)(rng()*12);keeper["household"]=household++;keeper["home"]=Home(door);keeper["work"]=new JsonObject{["place"]="logement",["kind"]="post",["at"]=KeeperPost(door)};
        var runner=A(Facts["keeperPrototypes"])[1]!.DeepClone().AsObject();runner["first"]=new[]{"Staf","Door","Rik","Miel"}[(int)(rng()*4)];runner["name"]=S(runner,"first")+" Verbiest";runner["age"]=29+(int)(rng()*12);runner["household"]=household;runner["home"]=Home(runnerDoor);var route=new JsonArray();foreach(var camp in A(Facts["camps"]).Take(4)){double x=V(camp![0]),z=V(camp[1])+4;var q=Snap?.Invoke(x,z,6)??(x,z);route.Add(new JsonArray(q.x,q.z));}runner["work"]=new JsonObject{["place"]="rijnkaai",["kind"]="roam",["route"]=route};var places=C.World("town")?["places"]as JsonObject;string? tavern=places?.Where(p=>p.Key.StartsWith("tavern:",StringComparison.Ordinal)).OrderBy(p=>D(N(p.Value,"x"),N(p.Value,"z"),N(runnerDoor,"sx"),N(runnerDoor,"sz"))).Select(p=>p.Key).FirstOrDefault();var day=new JsonArray(new JsonArray(9.5,15.5,"loiter","rijnkaai"));var sunday=new JsonArray(new JsonArray(10,15,"loiter","rijnkaai"));if(tavern!=null){day.Add(new JsonArray(18,22.5,"tavern",tavern));sunday.Add(new JsonArray(17,22.5,"tavern",tavern));}runner["sched"]=new JsonObject{["day"]=day,["sunday"]=sunday};
        var state=new JsonObject{["v"]=1,["seed"]=seed,["logement"]=Logement(door,shared),["keeper"]="em_keeper",["runner"]="em_runner",["runner_home"]=new JsonArray(N(runnerDoor,"sx"),N(runnerDoor,"sz")),["families"]=new JsonArray(),["scam"]=null,["scam_days"]=new JsonArray(),["runner_jailed"]=false,["notices"]=new JsonArray(),["errands"]=new JsonArray()};
        C.Atomic(()=>{foreach(var r in new[]{keeper,runner})if(C.Scalar<int>("SELECT COUNT(*) FROM npc WHERE id=$p0",S(r,"id"))==0)Insert(r);var town=C.World("town")!.AsObject();town["places"]!["logement"]=LogementPlace(door);for(int i=0;i<5;i++){var camp=A(Facts["camps"])[i]!;town["places"]!["emigrant_camp:"+i]=new JsonObject{["label"]="the emigrants' place on the Rijnkaai",["x"]=camp[0]!.DeepClone(),["z"]=camp[1]!.DeepClone(),["r"]=5,["district"]="rijnkaai"};}C.SetWorld("town",town);C.SetWorld("emigrants",state);});Invalidate?.Invoke();Tick(true);return true;
    }
    private void Rehouse(JsonObject state)
    {
        var lg=state["logement"]!.AsObject();var all=Doors!.Invoke();var kept=InworldHouses?.Invoke()??new HashSet<int>();bool Stands(JsonNode h,JsonNode step)=>all.Any(d=>N(d,"house")==V(h)&&D(N(d,"sx"),N(d,"sz"),V(step[0]),V(step[1]))<1);var runner=People.FirstOrDefault(r=>S(r,"id")==S(state,"runner"));bool listed=kept.Contains((int)N(lg,"house")),stale=listed||!Stands(lg["house"]!,lg["step"]!),runnerStale=runner!=null&&N(runner["home"],"house")>=0&&(kept.Contains((int)N(runner["home"],"house"))||!Stands(runner["home"]!["house"]!,new JsonArray(N(runner["home"],"sx"),N(runner["home"],"sz"))));if(!stale&&!runnerStale)return;var free=FreeDoors();var old=lg["step"]!.DeepClone();var picked=stale?PickLogement(free):(all.First(d=>N(d,"house")==N(lg,"house")),B(lg,"shared"));var door=picked.Item1;if(stale)state["logement"]=Logement(door,picked.Item2);var rdoor=runnerStale?free.Where(d=>N(d,"house")!=N(door,"house")).OrderBy(d=>D(N(d,"sx"),N(d,"sz"),-40,62)).FirstOrDefault()??door:null;
        foreach(var r in People.ToArray()){bool ours=!listed||S(r,"id")==S(state,"keeper")||N(r,"household")>=9000||S(r["work"],"place")=="logement";bool AtOld(JsonNode? p)=>p is JsonArray d&&D(V(d[0]),V(d[1]),V(old[0]),V(old[1]))<.5;if(stale&&ours&&AtOld(new JsonArray(N(r["home"],"sx"),N(r["home"],"sz"))))r["home"]=Home(door);if(stale&&AtOld(r["work"]?["door"]))r["work"]!["door"]=new JsonArray(N(door,"sx"),N(door,"sz"));if(stale&&S(r,"id")==S(state,"keeper"))r["work"]!["at"]=KeeperPost(door);if(rdoor!=null&&S(r,"id")==S(state,"runner")){r["home"]=Home(rdoor);state["runner_home"]=new JsonArray(N(rdoor,"sx"),N(rdoor,"sz"));}Insert(r);}if(stale){var town=C.World("town")!.AsObject();town["places"]!["logement"]=LogementPlace(door);C.SetWorld("town",town);}C.SetWorld("emigrants",state);Invalidate?.Invoke();
    }
    private bool Waiting(JsonObject state,JsonObject family)=>A(state["errands"]).Any(er=>N(er,"family")==N(family,"n")&&C.Scalar<string>("SELECT status FROM job WHERE id=$p0",(int)N(er,"job"))=="taken");
    private JsonObject Arrive(JsonObject state,int n,bool quiet)
    {
        var busy=A(state["families"]).Where(f=>S(f,"status")=="here").Select(f=>(int)N(f,"slot")).ToHashSet();int slot=0;while(busy.Contains(slot)&&slot<4)slot++;if(busy.Contains(slot))slot=n%5;var made=MakeFamily((uint)N(state,"seed"),n,slot,FamilyHome(state),A(state["families"]).Select(f=>S(f,"surname")));var family=made["family"]!.DeepClone().AsObject();family["slot"]=slot;family["props"]=made["props"]!.DeepClone();family["status"]="here";family["done"]=new JsonArray();C.Atomic(()=>{foreach(var person in A(made["residents"]).OfType<JsonObject>())Insert(person);});if(!quiet){C.Log(1,"emigrants_arrived",((int)N(family,"household")).ToString(),"The "+S(family,"surname")+" family, "+A(family["members"]).Count+" of them from "+S(family,"from")+" in "+S(family,"region")+", came to the Logement on the Rijnkaai to wait for the KEMPENLAND, bound for "+S(family,"bound").Split(',')[0]+".");host.Trade.Remember(1,S(state,"keeper"),"The "+S(family,"surname")+" family from "+S(Facts["origins"]?[S(family,"country")],"label")+" took beds at my house; they go out on the ship's day.",3);}return family;
    }
    private static JsonObject FamilyHome(JsonObject state){var lg=state["logement"]!;return new(){["house"]=lg["house"]!.DeepClone(),["x"]=lg["wall"]![0]!.DeepClone(),["z"]=lg["wall"]![1]!.DeepClone(),["sx"]=lg["step"]![0]!.DeepClone(),["sz"]=lg["step"]![1]!.DeepClone()};}
    private void Board(JsonObject state,JsonObject family,string by)
    {
        family["status"]="boarded";family["boarded"]=new JsonObject{["day"]=Day,["hour"]=(int)N(host.Clock.View(),"hour"),["by"]=by};C.Atomic(()=>{foreach(var member in A(family["members"])){string id=S(member);if(actions.Of(id)is {} action)actions.End((int)N(action,"id"),"stopped","went out to the ship");C.Execute("DELETE FROM resident WHERE id=$p0",id);C.Execute("UPDATE npc SET active=0 WHERE id=$p0",id);}foreach(var errand in A(state["errands"]).Where(er=>N(er,"family")==N(family,"n"))){int job=(int)N(errand,"job");C.Execute("UPDATE job SET status='expired' WHERE id=$p0 AND status='offered'",job);if(C.One("SELECT title,taken_by FROM job WHERE id=$p0 AND status='taken'",job)is {} row){int player=(int)N(row,"taken_by",1);C.Execute("UPDATE job SET status='failed' WHERE id=$p0",job);C.Execute("DELETE FROM item WHERE job_id=$p0 AND player_id=$p1",job,player);C.Log(player,"abandoned_job",job.ToString(),"The "+S(family,"surname")+" family went out to the ship before Jef finished \""+S(row,"title")+"\".");}}});if(state["scam"]is JsonObject scam&&N(scam,"family")==N(family,"n")&&S(scam,"state")=="working")scam["state"]="sold";C.Log(1,"emigrants_boarded",((int)N(family,"household")).ToString(),"The "+S(family,"surname")+" family went out by lighter to the KEMPENLAND at anchor, bound for "+S(family,"bound").Split(',')[0]+".");host.Trade.Remember(1,S(state,"keeper"),"The "+S(family,"surname")+" family left my house for the ship today.",2);
    }
    public JsonObject BoardByLighter(int household,bool dev=false)
    {
        var state=State;if(state==null)return new(){["ok"]=false,["why"]="no emigrants in this town"};var family=A(state["families"]).OfType<JsonObject>().FirstOrDefault(f=>N(f,"household")==household);if(family==null||S(family,"status")!="here")return new(){["ok"]=false,["why"]="no such family waiting"};if(!dev&&(N(family,"board_day")!=Day||Hour<7||Hour>=20))return new(){["ok"]=false,["why"]="their ship does not take them now"};if(!dev&&Waiting(state,family))return new(){["ok"]=false,["why"]="they are waiting for Jef"};Board(state,family,"lighter");C.SetWorld("emigrants",state);Invalidate?.Invoke();return new(){["ok"]=true};
    }
    public JsonObject Ship(){var state=State;return new(){["shipDay"]=IsShipDay(Day),["boardingNow"]=IsShipDay(Day)&&Hour>=7&&Hour<19,["nextShipDay"]=IsShipDay(Day)&&Hour<19?Day:NextShipDay(Day),["households"]=new JsonArray(A(state?["families"]).Where(f=>S(f,"status")=="here"&&N(f,"board_day")==Day).Select(f=>f!["household"]!.DeepClone()).ToArray()),["camp"]=new JsonObject{["x"]=31,["z"]=27},["berth"]=new JsonObject{["x"]=28,["z"]=1}};}
    public JsonObject View(bool residents=true)
    {
        var state=State;if(state==null)return new(){["families"]=new JsonArray(),["residents"]=new JsonArray()};var scam=state["scam"]is JsonObject s&&N(s,"day")==Day?s:null;var families=new JsonArray();foreach(var f in A(state["families"]).OfType<JsonObject>().Where(f=>S(f,"status")=="here")){var family=new JsonObject{["n"]=f["n"]!.DeepClone(),["household"]=f["household"]!.DeepClone(),["surname"]=S(f,"surname"),["from"]=S(f,"from")+", "+S(f,"region"),["country"]=S(Facts["origins"]?[S(f,"country")],"label"),["slot"]=f["slot"]!.DeepClone(),["members"]=f["members"]!.DeepClone(),["head"]=S(f,"head"),["baby"]=f["baby"]?.DeepClone(),["props"]=f["props"]!.DeepClone(),["board_day"]=f["board_day"]!.DeepClone(),["boarding_today"]=N(f,"board_day")==Day&&IsShipDay(Day),["waiting_for_jef"]=Waiting(state,f),["arrived_at"]=f["arrive"]!.DeepClone()};if(residents){var luggage=A(state["errands"]).Where(er=>N(er,"family")==N(f,"n")&&S(er,"kind")=="luggage").Select(er=>C.Scalar<string>("SELECT status FROM job WHERE source='emigrant' AND day=$p0 AND id=$p1",Day,(int)N(er,"job"))??"expired").ToArray();family["luggage"]=luggage.Any(st=>st is "done"or"failed")?"done":luggage.Contains("taken")?"taken":luggage.Contains("offered")?"offered":null;}families.Add(family);}
        var camps=new JsonArray();for(int i=0;i<5;i++){var p=A(Facts["camps"])[i]!;camps.Add(new JsonObject{["slot"]=i,["x"]=p[0]!.DeepClone(),["z"]=p[1]!.DeepClone(),["yaw"]=Math.PI});}var result=new JsonObject{["day"]=Day,["hour"]=Hour,["ship"]=new JsonObject{["today"]=IsShipDay(Day),["from"]=7,["to"]=19,["next"]=IsShipDay(Day)&&Hour<19?Day:NextShipDay(Day)},["logement"]=state["logement"]!.DeepClone(),["keeper"]=S(state,"keeper"),["arrival"]=new JsonArray(-56,24),["camps"]=camps,["families"]=families,["boarded"]=new JsonArray(A(state["families"]).Where(f=>S(f,"status")=="boarded"&&N(f?["boarded"],"day")==Day).Select(f=>(JsonNode)new JsonObject{["household"]=f!["household"]!.DeepClone(),["surname"]=S(f,"surname"),["by"]=S(f["boarded"],"by")}).ToArray()),["runner"]=new JsonObject{["id"]=S(state,"runner"),["jailed"]=B(state,"runner_jailed"),["working"]=S(scam,"state")=="working"?A(state["families"]).FirstOrDefault(f=>N(f,"n")==N(scam,"family"))?["household"]?.DeepClone():null,["state"]=scam?["state"]?.DeepClone()}};
        if(residents){var ids=new HashSet<string>{S(state,"keeper"),S(state,"runner")};foreach(var member in families.SelectMany(f=>A(f?["members"])))ids.Add(S(member));result["residents"]=new JsonArray(People.Where(p=>ids.Contains(S(p,"id"))).Select(p=>(JsonNode)new JsonObject{["id"]=S(p,"id"),["name"]=S(p,"name"),["first"]=S(p,"first"),["age"]=p["age"]!.DeepClone(),["sex"]=S(p,"sex"),["kind"]=S(p,"kind"),["trade"]=S(p,"trade"),["label"]=S(Facts["labels"],S(p,"trade"),S(p,"trade").Replace('_',' ')),["household"]=p["household"]!.DeepClone(),["role"]=S(p,"family_role"),["home"]=p["home"]!.DeepClone(),["work"]=p["work"]!.DeepClone(),["sched"]=p["sched"]!.DeepClone(),["dog"]=p["dog"]?.DeepClone(),["mate"]=p["mate"]?.DeepClone(),["wares"]=host.Trade.Wares(S(p,"id"))}).ToArray());}return result;
    }
    private void Push(JsonObject result){if(!B(result,"changed"))return;host.Publish("emigrants",new JsonObject{["arrived"]=A(result["arrived"]).Count,["boarded"]=A(result["boarded"]).Count});host.Publish("jobs",host.Payload(1));}
    public void Register(NativeServiceHost service)
    {
        service.Register("GET","/api/emigrants",r=>View());service.Register("POST","/api/emigrants/board",r=>{var result=BoardByLighter(r.Int("household"));if(B(result,"ok")){host.Publish("emigrants",new JsonObject{["boarded"]=1});host.Publish("jobs",host.Payload(r.PlayerId));}result["view"]=View();return result;});service.Register("POST","/api/dev/emigrants",Dev);
        service.TickAfterHooks.Add(_=>Push(Tick()));service.SleepEndedHooks.Add(_=>Push(Tick()));service.NewGame+=()=>{DevEarly.Clear();if(Doors!=null&&State==null)Ensure((uint)N(C.World("town"),"seed"));};service.Loaded+=()=>{DevEarly.Clear();if(State!=null){if(Doors!=null)Rehouse(State!);Tick(true);}};
    }
}

